contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(
        uint256 amount_,
        uint256 interest_,
        uint256 loanToCollateral_,
        uint256 duration_
    ) public {
        require(loanToCollateral_ > 0);
        require(duration_ > 0);

        c.requestLoan(amount_, interest_, loanToCollateral_, duration_); if (__ESBMC_reverted()) return;

        uint256 loanID = c.clearRequest(0, false, false); if (__ESBMC_reverted()) return;

        bool defaultedBefore = c.isDefaulted(loanID); if (__ESBMC_reverted()) return;

        bool reverted;
        c.claimDefaulted(loanID); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted == !defaultedBefore);
    }
}

